package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** Local decisions never impersonate a platform payment or a warehouse receipt. */
@Service public class RefundWorkspace {
    @Resource RefundService refunds;
    @Resource RefundReturnAutoCreate autoCreate;
    public Map<String,Object> detail(String company,long id){Map<String,Object> b=refunds.business(company,id,false);Map<String,Object> p=refunds.platform(company,number(b,"platform_refund_id"),false);b.put("platform",p);p.put("return_logistics",m("carrier_name",text(parse(text(p,"payload")),"company_name"),"waybill",text(parse(text(p,"payload")),"sid"),"address",text(parse(text(p,"payload")),"address"),"source","PLATFORM"));p.remove("payload");b.put("approved_snapshot",obj(b.get("approved_snapshot")));b.put("events",refunds.repository.db().query("SELECT id,action,message,actor,create_time FROM oms_refund_event WHERE company_code=? AND refund_id=? ORDER BY id DESC LIMIT 100",ROW,company,id));
        b.put("lines",refunds.repository.db().query("SELECT l.id,l.platform_oid,l.sku_sn,l.goods_name,l.quantity,l.cancelled_quantity,l.reserved_quantity,l.business_type,l.exchange_id,l.stock_reference,l.bundle_id,l.component_quantity,l.gift_plan_id,l.stocked_bundle_snapshot,p.platform_spec FROM oms_order_line l LEFT JOIN oms_platform_order_line p ON p.company_code=l.company_code AND p.platform_order_id=? AND p.platform_oid=l.platform_oid WHERE l.company_code=? AND l.order_id=? AND l.platform_oid=? ORDER BY l.id LIMIT 500",ROW,b.get("original_platform_order_id"),company,b.get("order_id"),b.get("platform_oid")));
        b.putAll(refunds.repository.db().queryForMap("SELECT b.id"+RefundReturnSummary.columns()+" FROM oms_refund b WHERE b.company_code=? AND b.id=?",company,id));
        RefundReturnSummary.decorate(refunds.repository,company,Collections.singletonList(b));
        Map<String,Object> original=refunds.repository.db().queryForMap("SELECT document_info FROM oms_order WHERE company_code=? AND id=?",company,b.get("order_id"));Map<String,Object> doc=OrderDocumentInfo.stored(original.get("document_info"));Map<String,Object> sales=new LinkedHashMap<>();Object rawLines=doc.get("lines");if(rawLines instanceof List)for(Object item:(List<?>)rawLines)if(item instanceof Map&&text(b,"platform_oid").equals(String.valueOf(((Map<?,?>)item).get("platform_oid")))){sales.putAll((Map<String,Object>)item);break;}b.put("sales_context",m("line",sales,"source_modified",doc.get("source_modified"),"buyer_freight",doc.get("buyer_freight")));
        b.put("shipments",refunds.repository.db().query("SELECT s.id shipment_id,s.shipment_sn,s.business_type,s.exchange_id,s.status,l.id shipment_line_id,l.order_line_id,l.sku_sn,l.goods_name,l.quantity,l.shipped_quantity,l.store_code,l.batch_id,l.platform_oid FROM oms_order_shipment s JOIN oms_order_shipment_line l ON l.company_code=s.company_code AND l.shipment_id=s.id JOIN oms_order_line ol ON ol.company_code=l.company_code AND ol.id=l.order_line_id WHERE s.company_code=? AND s.order_id=? AND ol.platform_oid=? ORDER BY s.id,l.id LIMIT 100",ROW,company,b.get("order_id"),b.get("platform_oid")));
        List<Map<String,Object>> kits=OrderBundles.report(refunds.repository,company,number(b,"order_id"));kits.removeIf(kit->!text(b,"platform_oid").equals(text(kit,"platform_oid")));b.put("bundles",kits);
        RefundReturnAutoCreate.decorate(refunds.repository,company,Collections.singletonList(b));RefundParcelIssues.decorate(refunds.repository,company,Collections.singletonList(b));b.put("capability",m("platform_payment",false,"warehouse_return",true,"message","退款退回支持独立安排、下发、截单、实收及入账。创建安排不增加库存；资金结果仍以平台同步为准。"));return b;
    }
    public Map<String,Object> review(String company,long id,Map<String,Object> body,String actor){Map<String,Object> hint=refunds.business(company,id,false);return refunds.tx().execute(s->{refunds.lockOriginal(company,number(hint,"channel_id"),text(hint,"platform_tid"));Map<String,Object> p=refunds.platform(company,number(hint,"platform_refund_id"),true),b=refunds.business(company,id,true);require(number(body,"control_version")==number(b,"control_version")&&number(body,"platform_version")==number(p,"version"),"退款或平台版本已变化，请刷新后审核");require("VALID".equals(text(p,"source_state"))&&Arrays.asList("REFUND","REFUND_AND_RETURN").contains(text(p,"dispute_type")),"平台退款资料有异常或已变为其他类型，请核对");require(!"CLOSED".equals(text(p,"platform_status")),"平台申请已关闭，请核对关闭前是否已执行货物操作");String purpose=text(body,"purpose"),goods=text(body,"goods_action"),reason=required(body,"reason",500),evidence=required(body,"evidence",1000);require(Arrays.asList("CANCEL","DIFFERENCE","COMPENSATION","POSTAGE","OTHER","PLATFORM_SPECIAL").contains(purpose),"请选择明确的退款用途");require(Arrays.asList("KEEP","CANCEL","INTERCEPT","REFUSAL","RETURN").contains(goods),"请选择明确的货物处理方式");if("REFUND_AND_RETURN".equals(text(p,"dispute_type")))require(Arrays.asList("RETURN","REFUSAL","INTERCEPT").contains(goods),"退货退款须明确退回、拒收或拦截方案；无需退回请先核对平台申请类型");require(!("CANCEL".equals(purpose)&&"KEEP".equals(goods)),"取消商品退款不能选择继续履约");
            if(Arrays.asList("INTERCEPT","REFUSAL","RETURN").contains(goods))require(refunds.repository.db().queryForObject("SELECT COALESCE(SUM(l.shipped_quantity),0) FROM oms_order_shipment_line l JOIN oms_order_shipment sh ON sh.company_code=l.company_code AND sh.id=l.shipment_id WHERE l.company_code=? AND sh.order_id=? AND l.platform_oid=?",Long.class,company,b.get("order_id"),b.get("platform_oid"))>0,"尚无实际出库记录，请选择未发货取消或继续履约");
            long line=number(body,"cancel_line_id"),qty=number(body,"cancel_quantity");if("CANCEL".equals(goods)){List<Map<String,Object>> rows=refunds.repository.db().query("SELECT * FROM oms_order_line WHERE company_code=? AND order_id=? AND id=? AND platform_oid=? FOR UPDATE",ROW,company,b.get("order_id"),line,b.get("platform_oid"));require(rows.size()==1&&qty>0&&qty<=number(rows.get(0),"quantity")-number(rows.get(0),"cancelled_quantity")-refunds.repository.db().queryForObject("SELECT COALESCE(SUM(shipped_quantity),0) FROM oms_order_shipment_line WHERE company_code=? AND order_line_id=?",Long.class,company,line),"请选择本子订单的实际商品及明确取消数量");}else require(qty==0&&line==0,"当前货物方案不应携带取消商品数量");
            require(refunds.repository.db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=?",Long.class,company,id)==0||(goods.equals(text(b,"goods_action"))&&purpose.equals(text(b,"purpose"))),"已有退回安排，不能改写货物方案，请在原安排截单或差异结案");require(b.get("cancel_command")==null&&number(b,"cancelled_quantity")==0,"已有执行记录，不能覆盖原执行方案");String goodsState="KEEP".equals(goods)?"DONE":refunds.repository.db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=?",Long.class,company,id)>0?text(b,"goods_state"):"WAIT_ACTION",funds=text(b,"funds_state"),state="SUCCESS".equals(funds)&&"DONE".equals(goodsState)?"COMPLETED":"PROCESSING";
            refunds.repository.db().update("UPDATE oms_refund SET state=?,review_state='APPROVED',purpose=?,goods_action=?,goods_state=?,approved_version=?,approved_hash=?,approved_snapshot=?,refund_fee=?,cancel_line_id=?,cancel_quantity=?,review_reason=?,review_evidence=?,review_by=?,reviewed_at=NOW(),problem_code='',problem_message='',control_version=control_version+1 WHERE company_code=? AND id=?",state,purpose,goods,goodsState,p.get("version"),planFingerprint(parse(text(p,"payload"))),p.get("payload"),p.get("refund_fee"),line==0?null:line,qty,reason,evidence,actor,company,id);
            refunds.event(company,id,"REVIEW","审核用途："+purpose+"；货物方案："+goods+"；依据："+reason+"；凭证："+evidence+"。本次未调用平台付款或修改库存。",actor);if(autoCreate!=null)autoCreate.enqueue(company,id);RefundGuard.refresh(refunds.repository,company,number(b,"channel_id"),text(b,"platform_tid"));return m("id",id,"state",state);
        });}
    public Map<String,Object> records(String company,long order){require(refunds.repository.db().queryForObject("SELECT COUNT(*) FROM oms_order WHERE company_code=? AND id=?",Long.class,company,order)==1,"业务订单不存在或无权访问");return m("platform",refunds.repository.db().query("SELECT p.id,p.refund_id,p.platform_oid,p.platform_status,p.refund_fee,p.conversion_state,p.conversion_error,p.source_state,p.source_error,p.business_refund_id FROM oms_platform_refund p JOIN oms_order o ON o.company_code=p.company_code AND o.channel_id=p.channel_id AND o.platform_tid=p.platform_tid WHERE o.company_code=? AND o.id=? ORDER BY p.id DESC LIMIT 100",ROW,company,order),"business",refunds.repository.db().query("SELECT id,refund_sn,refund_id,platform_oid,purpose,goods_action,goods_state,funds_state,review_state,state FROM oms_refund WHERE company_code=? AND order_id=? ORDER BY id DESC LIMIT 100",ROW,company,order));}
}
